def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marks = [[grid[r][c] != bg for c in range(w)] for r in range(h)]
    active_cols = [c for c in range(w) if sum(marks[r][c] for r in range(h)) >= 3]

    if not active_cols:
        return [row[:] for row in grid]

    rows = [r for r in range(h) if any(marks[r])]
    top, bottom = min(rows), max(rows)
    out = [row[:] for row in grid]

    for c in active_cols:
        for r in range(top, bottom + 1):
            if grid[r][c] == bg:
                out[r][c] = 2

    left, right = min(active_cols), max(active_cols)
    for r in (top, bottom):
        for c in range(left, right + 1):
            if grid[r][c] == bg:
                out[r][c] = 2

    return out
